export interface PageData {
  title?: string;
  date?: string;
  tags?: string[];
}

export interface Page {
  slug: string;
  content: string;
  html: string;
  data: PageData;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';
import { Page, PageData } from './types';

function slugify(filePath: string): string {
  const base = path.basename(filePath, path.extname(filePath));
  const slug = base
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return slug || 'page';
}

function toTags(raw: unknown): string[] | undefined {
  if (!raw) return undefined;
  if (Array.isArray(raw)) return raw.map((t) => String(t));
  return String(raw)
    .split(',')
    .map((t) => t.trim())
    .filter((t) => t.length > 0);
}

function toData(frontmatter: Record<string, unknown>): PageData {
  return {
    title: typeof frontmatter.title === 'string' ? frontmatter.title : undefined,
    date: typeof frontmatter.date === 'string' ? frontmatter.date : undefined,
    tags: toTags(frontmatter.tags),
  };
}

export function parseMarkdown(filePath: string): Page {
  const raw = fs.readFileSync(filePath, 'utf-8');
  const { content, data } = matter(raw);
  const html = marked.parse(content, { async: false });
  return {
    slug: slugify(filePath),
    content,
    html,
    data: toData(data),
  };
}

import { Page } from './types';

function esc(value: string): string {
  return value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function pageTitle(page: Page): string {
  return page.data.title || page.slug;
}

function tagsHtml(tags: string[] | undefined): string {
  if (!tags || tags.length === 0) return '';
  const items = tags.map((t) => `<span class="tag">${esc(t)}</span>`).join('');
  return `<div class="tags">${items}</div>`;
}

export function renderPage(page: Page): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>${esc(pageTitle(page))}</title>
</head>
<body>
  <header>
    <nav><a href="index.html">Home</a></nav>
  </header>
  <main>
    <h1>${esc(pageTitle(page))}</h1>
    ${page.data.date ? `<time datetime="${esc(page.data.date)}">${esc(page.data.date)}</time>` : ''}
    ${tagsHtml(page.data.tags)}
    <article>
${page.html}
    </article>
  </main>
</body>
</html>
`;
}

export function renderIndex(pages: Page[]): string {
  const sorted = [...pages].sort((a, b) => {
    const da = a.data.date || '';
    const db = b.data.date || '';
    if (da !== db) return da < db ? 1 : -1;
    return a.slug.localeCompare(b.slug);
  });

  const items = sorted
    .map(
      (p) => `    <li>
      <a href="${p.slug}.html">${esc(pageTitle(p))}</a>
      ${p.data.date ? `<time datetime="${esc(p.data.date)}">${esc(p.data.date)}</time>` : ''}
    </li>`
    )
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Home</title>
</head>
<body>
  <main>
    <h1>Pages</h1>
    <ul>
${items}
    </ul>
  </main>
</body>
</html>
`;
}

import fs from 'fs';
import path from 'path';
import { Page, BuildOptions } from './types';
import { parseMarkdown } from './parse';
import { renderIndex, renderPage } from './render';

export function collectPages(contentDir: string): Page[] {
  if (!fs.existsSync(contentDir)) {
    throw new Error(`Content directory does not exist: ${contentDir}`);
  }
  const entries = fs.readdirSync(contentDir, { withFileTypes: true });
  return entries
    .filter((e) => e.isFile() && e.name.endsWith('.md'))
    .sort((a, b) => a.name.localeCompare(b.name))
    .map((e) => parseMarkdown(path.join(contentDir, e.name)));
}

export function buildSite(options: BuildOptions): Page[] {
  const { contentDir, outputDir } = options;

  const pages = collectPages(contentDir);

  fs.rmSync(outputDir, { recursive: true, force: true });
  fs.mkdirSync(outputDir, { recursive: true });

  for (const page of pages) {
    fs.writeFileSync(path.join(outputDir, `${page.slug}.html`), renderPage(page), 'utf-8');
  }

  fs.writeFileSync(path.join(outputDir, 'index.html'), renderIndex(pages), 'utf-8');

  return pages;
}

#!/usr/bin/env node
import path from 'path';
import { buildSite } from './build';

export interface CliArgs {
  contentDir: string;
  outputDir: string;
  showHelp: boolean;
  command: string | undefined;
}

const HELP = `Usage: ssg [command] [options]

Commands:
  build       Generate the site from markdown content (default)

Options:
  --content <dir>   Content directory containing markdown files (default: ./content)
  --output <dir>    Output directory for generated HTML (default: ./dist)
  -h, --help        Show this help message
`;

export function parseArgs(argv: string[]): CliArgs {
  const args: CliArgs = {
    contentDir: 'content',
    outputDir: 'dist',
    showHelp: false,
    command: undefined,
  };

  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];
    switch (arg) {
      case '-h':
      case '--help':
        args.showHelp = true;
        break;
      case 'build':
        args.command = 'build';
        break;
      case '--content':
      case '--output': {
        const next = argv[i + 1];
        if (next === undefined || next.startsWith('-')) {
          throw new Error(`Option ${arg} requires a value`);
        }
        if (arg === '--content') args.contentDir = next;
        else args.outputDir = next;
        i += 1;
        break;
      }
      default:
        throw new Error(`Unknown option or command: ${arg}`);
    }
    i += 1;
  }

  return args;
}

export function run(argv: string[]): number {
  let args: CliArgs;
  try {
    args = parseArgs(argv);
  } catch (err) {
    console.error(`Error: ${(err as Error).message}`);
    console.error(HELP);
    return 1;
  }

  if (args.showHelp) {
    process.stdout.write(HELP);
    return 0;
  }

  const contentDir = path.resolve(process.cwd(), args.contentDir);
  const outputDir = path.resolve(process.cwd(), args.outputDir);

  try {
    const pages = buildSite({ contentDir, outputDir });
    console.log(`Built ${pages.length} page${pages.length === 1 ? '' : 's'} into ${outputDir}`);
    return 0;
  } catch (err) {
    console.error(`Error: ${(err as Error).message}`);
    return 1;
  }
}

if (require.main === module) {
  process.exit(run(process.argv.slice(2)));
}

import fs from 'fs';
import os from 'os';
import path from 'path';
import { parseMarkdown } from './parse';

function writeTemp(dir: string, name: string, content: string): string {
  const p = path.join(dir, name);
  fs.writeFileSync(p, content, 'utf-8');
  return p;
}

describe('parseMarkdown', () => {
  let dir: string;

  beforeEach(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-parse-'));
  });

  afterEach(() => {
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it('parses body and slug from a markdown file', () => {
    const file = writeTemp(dir, 'hello-world.md', '# Hello\n\nSome **bold** text.');
    const page = parseMarkdown(file);

    expect(page.slug).toBe('hello-world');
    expect(page.html).toContain('<h1>Hello</h1>');
    expect(page.html).toContain('<strong>bold</strong>');
    expect(page.data.title).toBeUndefined();
  });

  it('parses frontmatter title, date, and tags', () => {
    const file = writeTemp(
      dir,
      'post.md',
      '---\ntitle: My First Post\ndate: 2024-01-02\ntags:\n  - typescript\n  - ssg\n---\n\nBody text.'
    );
    const page = parseMarkdown(file);

    expect(page.data.title).toBe('My First Post');
    expect(page.data.date).toBe('2024-01-02');
    expect(page.data.tags).toEqual(['typescript', 'ssg']);
    expect(page.html).toContain('<p>Body text.</p>');
  });

  it('parses tags as a comma-separated string', () => {
    const file = writeTemp(dir, 'c.md', '---\ntags: alpha, beta\n---\n\nx');
    const page = parseMarkdown(file);
    expect(page.data.tags).toEqual(['alpha', 'beta']);
  });

  it('produces a safe slug from tricky filenames', () => {
    const file = writeTemp(dir, 'My  Article--Name.md', '---\n---\n\nx');
    const page = parseMarkdown(file);
    expect(page.slug).toBe('my-article-name');
  });
});

import { Page } from './types';
import { renderIndex, renderPage } from './render';

function makePage(overrides: Partial<Page> = {}): Page {
  return {
    slug: 'about',
    content: '# About',
    html: '<h1>About</h1>',
    data: {},
    ...overrides,
  };
}

describe('renderPage', () => {
  it('uses the frontmatter title in the <title> and <h1>', () => {
    const html = renderPage(makePage({ data: { title: 'About Me' } }));
    expect(html).toContain('<title>About Me</title>');
    expect(html).toContain('<h1>About Me</h1>');
  });

  it('falls back to the slug for the title', () => {
    const html = renderPage(makePage({ slug: 'my-page' }));
    expect(html).toContain('<title>my-page</title>');
    expect(html).toContain('<h1>my-page</h1>');
  });

  it('renders the date and tags when present', () => {
    const html = renderPage(
      makePage({ data: { date: '2024-01-02', tags: ['a', 'b'] } })
    );
    expect(html).toContain('<time datetime="2024-01-02">2024-01-02</time>');
    expect(html).toContain('class="tag">a</span>');
    expect(html).toContain('class="tag">b</span>');
  });

  it('escapes unsafe title characters', () => {
    const html = renderPage(makePage({ data: { title: 'A <B> & "C"' } }));
    expect(html).toContain('&lt;B&gt;');
    expect(html).not.toContain('<B>');
  });
});

describe('renderIndex', () => {
  it('links every page by slug', () => {
    const pages = [
      makePage({ slug: 'a', data: { title: 'A' } }),
      makePage({ slug: 'b', data: { title: 'B' } }),
    ];
    const html = renderIndex(pages);
    expect(html).toContain('<a href="a.html">A</a>');
    expect(html).toContain('<a href="b.html">B</a>');
  });

  it('sorts pages by date descending', () => {
    const pages = [
      makePage({ slug: 'old', data: { date: '2023-01-01' } }),
      makePage({ slug: 'new', data: { date: '2024-01-01' } }),
    ];
    const html = renderIndex(pages);
    expect(html.indexOf('new.html')).toBeLessThan(html.indexOf('old.html'));
  });
});

import fs from 'fs';
import os from 'os';
import path from 'path';
import { buildSite, collectPages } from './build';

describe('buildSite', () => {
  let root: string;
  let contentDir: string;
  let outputDir: string;

  beforeEach(() => {
    root = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-build-'));
    contentDir = path.join(root, 'content');
    outputDir = path.join(root, 'dist');
    fs.mkdirSync(contentDir);
  });

  afterEach(() => {
    fs.rmSync(root, { recursive: true, force: true });
  });

  function writeContent(name: string, content: string): void {
    fs.writeFileSync(path.join(contentDir, name), content, 'utf-8');
  }

  it('generates an index.html and a page per markdown file', () => {
    writeContent('first.md', '---\ntitle: First\ndate: 2024-01-01\n---\n\nHello *world*.');
    writeContent('second.md', '---\ntitle: Second\n---\n\nSecond body.');

    const pages = buildSite({ contentDir, outputDir });

    expect(pages).toHaveLength(2);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'first.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'second.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'README.txt'))).toBe(false);

    const index = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf-8');
    expect(index).toContain('<a href="first.html">First</a>');
    expect(index).toContain('<a href="second.html">Second</a>');

    const page = fs.readFileSync(path.join(outputDir, 'first.html'), 'utf-8');
    expect(page).toContain('<em>world</em>');
    expect(page).toContain('<time datetime="2024-01-01">2024-01-01</time>');
  });

  it('ignores non-markdown files', () => {
    writeContent('keep.md', '---\ntitle: Keep\n---\n\nx');
    fs.writeFileSync(path.join(contentDir, 'notes.txt'), 'not markdown', 'utf-8');
    fs.writeFileSync(path.join(contentDir, 'image.png'), 'fake', 'utf-8');

    const pages = buildSite({ contentDir, outputDir });

    expect(pages).toHaveLength(1);
    expect(fs.existsSync(path.join(outputDir, 'keep.html'))).toBe(true);
  });

  it('cleans the output directory before writing', () => {
    writeContent('a.md', '---\ntitle: A\n---\n\nx');
    fs.mkdirSync(outputDir, { recursive: true });
    fs.writeFileSync(path.join(outputDir, 'stale.html'), 'stale', 'utf-8');

    buildSite({ contentDir, outputDir });

    expect(fs.existsSync(path.join(outputDir, 'stale.html'))).toBe(false);
    expect(fs.existsSync(path.join(outputDir, 'a.html'))).toBe(true);
  });

  it('throws when the content directory does not exist', () => {
    expect(() => buildSite({ contentDir: path.join(root, 'nope'), outputDir })).toThrow(
      'does not exist'
    );
  });
});

describe('collectPages', () => {
  it('returns no pages for an empty directory', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-empty-'));
    try {
      const pages = collectPages(dir);
      expect(pages).toEqual([]);
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });
});

import { parseArgs } from './cli';

describe('parseArgs', () => {
  it('uses defaults when no options are given', () => {
    const args = parseArgs(['build']);
    expect(args.command).toBe('build');
    expect(args.contentDir).toBe('content');
    expect(args.outputDir).toBe('dist');
    expect(args.showHelp).toBe(false);
  });

  it('parses --content and --output values', () => {
    const args = parseArgs(['build', '--content', 'src/md', '--output', 'public']);
    expect(args.contentDir).toBe('src/md');
    expect(args.outputDir).toBe('public');
  });

  it('sets the help flag', () => {
    const args = parseArgs(['--help']);
    expect(args.showHelp).toBe(true);
  });

  it('throws on an unknown option', () => {
    expect(() => parseArgs(['--bogus'])).toThrow('Unknown option or command');
  });

  it('throws when an option is missing its value', () => {
    expect(() => parseArgs(['build', '--content'])).toThrow('requires a value');
  });
});

